package net.sunlightsmp.playersettings;
import org.bukkit.*;import org.bukkit.block.Block;import org.bukkit.entity.Player;import org.bukkit.event.*;import org.bukkit.event.player.PlayerInteractEvent;import org.bukkit.inventory.*;import org.bukkit.inventory.meta.ItemMeta;import org.bukkit.persistence.PersistentDataType;import java.util.*;
public final class SunlightBucket implements Listener{
 private final NamespacedKey marker,expiry;public SunlightBucket(SunlightPlayerSettings p){marker=new NamespacedKey(p,"sunlight_bucket");expiry=new NamespacedKey(p,"sunlight_bucket_expiry");}
 public ItemStack create(){ItemStack i=new ItemStack(Material.BUCKET);ItemMeta m=i.getItemMeta();m.setDisplayName(ChatColor.GOLD+"☀ Sunlight Bucket");m.setLore(List.of(ChatColor.GRAY+"Drains 24 water source blocks at once.",ChatColor.GREEN+"24 SOURCE DRAIN",ChatColor.DARK_GRAY+"Temporary Sunlight tool"));m.setUnbreakable(true);m.getPersistentDataContainer().set(marker,PersistentDataType.BYTE,(byte)1);m.getPersistentDataContainer().set(expiry,PersistentDataType.LONG,System.currentTimeMillis()+2L*24*60*60*1000);i.setItemMeta(m);return i;}
 private boolean isTool(ItemStack i){if(i==null||i.getType()!=Material.BUCKET||!i.hasItemMeta())return false;Byte b=i.getItemMeta().getPersistentDataContainer().get(marker,PersistentDataType.BYTE);return b!=null&&b==1;}
 private boolean expired(ItemStack i){Long t=i.getItemMeta().getPersistentDataContainer().get(expiry,PersistentDataType.LONG);return t==null||System.currentTimeMillis()>=t;}
 @EventHandler(priority=EventPriority.HIGH,ignoreCancelled=true) public void use(PlayerInteractEvent e){if(e.getAction()!=org.bukkit.event.block.Action.RIGHT_CLICK_BLOCK)return;Player p=e.getPlayer();ItemStack tool=p.getInventory().getItemInMainHand();if(!isTool(tool))return;if(expired(tool)){e.setCancelled(true);p.getInventory().setItemInMainHand(null);p.sendMessage(ChatColor.RED+"☀ Your Sunlight Bucket has expired.");return;}Block clicked=e.getClickedBlock();if(clicked==null||clicked.getType()!=Material.WATER){p.sendMessage(ChatColor.YELLOW+"☀ Click a water source to drain it.");return;}int drained=0;Set<Block> seen=new HashSet<>();ArrayDeque<Block> q=new ArrayDeque<>();q.add(clicked);e.setCancelled(true);while(!q.isEmpty()&&drained<24){Block b=q.poll();if(!seen.add(b)||b.getType()!=Material.WATER)continue;int level=b.getBlockData() instanceof org.bukkit.block.data.Levelled l?l.getLevel():0;if(level!=0)continue;b.setType(Material.AIR,false);drained++;for(int dx=-1;dx<=1;dx++)for(int dy=-1;dy<=1;dy++)for(int dz=-1;dz<=1;dz++)if(Math.abs(dx)+Math.abs(dy)+Math.abs(dz)==1){Block n=b.getRelative(dx,dy,dz);if(!seen.contains(n)&&n.getType()==Material.WATER)q.add(n);}}p.sendMessage(ChatColor.GREEN+"☀ Drained "+ChatColor.YELLOW+drained+ChatColor.GREEN+" water sources.");p.playSound(p.getLocation(),Sound.ITEM_BUCKET_FILL,1f,1.1f);}
}